local adapter = require("libtmux.runtime.luv")

local function must(value, err)
    if err ~= nil then error(err, 0) end
    return value
end

local binary = assert(os.getenv("TMUX_BIN"), "Set TMUX_BIN")
local socket = assert(os.getenv("TMUX_SOCKET"), "Use run.sh")
local result = must(adapter.run(function(runtime)
    local server = must(runtime:connect({
        binary = binary, socket_path = socket,
    }):await())

    local created = must(server:new_session({
        name = "quickstart", window_name = "main",
        argv = { "/bin/sh" },
    }):await())
    local logs = must(created.session:new_window({
        name = "logs", argv = { "/bin/cat" },
    }):await())
    local split = must(logs.pane:split({
        direction = "right", percent = 40,
        argv = { "/bin/cat" },
    }):await())

    -- Signal completion on this private server, not a fixed sleep.
    local marker = "libtmux-lua-quickstart"
    local signal = ("printf '\\nlibtmux ready\\n'; "
        .. "'%s' wait-for -S %s"):format(binary, marker)
    must(created.pane:send_text(signal):await())
    must(created.pane:send_keys({ "Enter" }):await())
    must(server:command(
        { "wait-for", marker }, { timeout = 10000 }
    ):await())
    local capture = must(created.pane:capture({
        history_lines = 20,
    }):await())
    assert(must(capture:text()):find(
        "\nlibtmux ready\n", 1, true
    ), "pane output was not captured")
    print(
        created.session:reference().id,
        logs.window:reference().id,
        split.pane:reference().id
    )
    must(created.session:kill():await())
    must(server:close():await())
    return true
end))
assert(result)

import { mkdtemp, readdir, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { setTimeout as delay } from "node:timers/promises";
import { Server } from "libtmux";

const directory = await mkdtemp(join(tmpdir(), "ltx-home-"));
const server = new Server({
  socketPath: join(directory, "tmux.sock"),
  configFile: "/dev/null",
  timeoutMs: 5_000,
});
const failures: unknown[] = [];
try {
  const signal = AbortSignal.timeout(5_000);
  const session = await server.newSession({ name: "work", signal });
  const editor = await session.newWindow({
    name: "editor", shellCommand: "sh", signal,
  });
  await editor.split({ signal });
  const pane = editor.activePane;
  if (!pane) throw new Error("The window has no active pane");

  await pane.sendKeys("printf '\\nhello\\n'", { signal });
  for (;;) {
    const lines = await pane.capture({ signal });
    if (lines.includes("hello")) {
      console.log("hello");
      break;
    }
    await delay(20, undefined, { signal });
  }
} catch (error) {
  failures.push(error);
} finally {
  try {
    if ((await readdir(directory)).includes("tmux.sock")) {
      await server.kill();
    }
    await rm(directory, { recursive: true });
  } catch (error) {
    failures.push(new Error(`Cleanup failed: ${directory}`, {
      cause: error,
    }));
  }
}
if (failures.length) throw new AggregateError(failures);

use libtmux::{PaneWait, Server};
use std::{error::Error, time::Duration};

type ExampleError = Box<dyn Error>;

async fn work(server: &Server) -> Result<(), ExampleError> {
    let session = server.new_session("work").await?;
    let window = session.new_window("editor").await?;
    let pane = window.active_pane().await?.ok_or("missing pane")?;

    pane.send_line("printf '\\nhello\\n'").await?;
    let seen = pane
        .wait_until(Duration::from_secs(5), |lines| {
            lines.iter().any(|line| *line == "hello")
        })
        .await?;
    if seen != PaneWait::Arrived {
        return Err("The pane did not print hello".into());
    }
    for line in pane.capture().await? {
        if line == "hello" {
            println!("{}", line.to_string_lossy());
        }
    }
    Ok(())
}

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<(), ExampleError> {
    let root = std::path::Path::new("/tmp/libtmux-rs-dev");
    std::fs::create_dir_all(root)?;
    let directory =
        tempfile::Builder::new().prefix("home-").tempdir_in(root)?;
    let server = Server::builder()
        .socket_path(directory.path().join("tmux.sock"))
        .config_file("/dev/null")
        .default_timeout(Duration::from_secs(5))
        .build()?;
    let outcome =
        tokio::time::timeout(Duration::from_secs(10), work(&server))
            .await;

    // kill stops our daemon; shutdown closes this client executor.
    let killed = server.kill().await;
    let closed = server.shutdown().await;
    let cleanup_failed = killed.is_err() || closed.is_err();
    let mut failures = Vec::new();
    match outcome {
        Ok(Ok(())) => {}
        Ok(Err(error)) => failures.push(format!("work: {error}")),
        Err(error) => failures.push(format!("deadline: {error}")),
    }
    if let Err(error) = killed {
        failures.push(format!("stop owned daemon: {error}"));
    }
    if let Err(error) = closed {
        failures.push(format!("close executor: {error}"));
    }
    if cleanup_failed {
        let retained = directory.keep();
        failures.push(format!("inspect {}", retained.display()));
    } else if let Err(error) = directory.close() {
        failures.push(format!("remove directory: {error}"));
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; ").into())
    }
}

