import io.github.libtmux.Server;
import io.github.libtmux.ServerConfig;
import io.github.libtmux.ServerEndpoint;
import io.github.libtmux.TextOutcome;
import java.nio.file.Path;
import java.time.Duration;

public final class Main {
    public static void main(String[] args) throws Exception {
        if (args.length != 3) {
            throw new IllegalArgumentException(
                    "expected tmux, socket and config paths");
        }
        var config = ServerConfig.builder()
                .binary(args[0])
                .endpoint(ServerEndpoint.socketPath(Path.of(args[1])))
                .configFile(Path.of(args[2]))
                .build();

        try (Server server = Server.open(config)) {
            var session = server.newSession("demo");
            var window = session.newWindow("build");
            var pane = window.split();

            pane.sendLine("printf 'hello from %s\\n' libtmux");
            if (pane.awaitText("hello from libtmux", Duration.ofSeconds(5))
                    == TextOutcome.TIMED_OUT) {
                throw new IllegalStateException("output did not arrive");
            }
            var lines = pane.capture();
            if (lines.stream().noneMatch(
                    line -> line.strip().equals("hello from libtmux"))) {
                throw new IllegalStateException(
                        "capture is missing the output line");
            }
            System.out.println("hello from libtmux");
        }
    }
}

