import io.github.libtmux.{ServerConfig, ServerEndpoint}
import io.github.libtmux.scaladsl.{config => _, *}
import java.nio.file.Path
import scala.util.Using

object Main {
  def main(args: Array[String]): Unit = {
    require(args.length == 3, "expected tmux, socket and config paths")
    val config = ServerConfig.builder()
      .binary(args(0))
      .endpoint(ServerEndpoint.socketPath(Path.of(args(1))))
      .configFile(Path.of(args(2)))
      .build()

    Using.resource(Server.open(config)) { server =>
      val panes = server.panes()
      val named = panes.filter(_.info.title().nonEmpty)
      val commands = named.map(_.info.currentCommand())
      assert(panes.nonEmpty)
      assert(commands.size <= panes.size)
      assert(panes.forall { pane =>
        pane.window.info.context().equals(pane.info.context())
      })
      println(s"panes=${panes.size}; related windows verified")
    }
  }
}

