{
    SocketName = "quickstart-" + Guid.NewGuid().ToString("N"),
    ConfigurationFile = "/dev/null",
    TmuxBinaryPath = Environment.GetEnvironmentVariable("LIBTMUX_TMUX")
        ?? "tmux",
};

await using var owned = await Server.CreateOwnedAsync(options, token);
Server server = owned.Value;
Session session = await server.CreateSessionAsync(
    new NewSessionRequest { Name = "build", Command = "/bin/sh" },
    token);
Window window = await session.CreateWindowAsync(
    new NewWindowRequest { Name = "tests", Command = "/bin/sh" },
    token);
Pane pane = (await window.GetPanesAsync(token))[0];

await pane.SendTextAsync(
    "printf 'hello-from-%s\\n' libtmux",
    enter: false, cancellationToken: token);
await pane.EnterAsync(token);
var lines = await TmuxWait.UntilAsync(
    async cancellation => await pane.CaptureAsync(
        cancellationToken: cancellation),
    output => output.Any(line => line.TrimEnd() == "hello-from-libtmux"),
    TimeSpan.FromSeconds(10),
    TimeSpan.FromMilliseconds(20),
    token);
Console.WriteLine("hello-from-libtmux");

