#include <chrono>
#include <cstdio>
#include <libtmux/libtmux.hpp>

int main(int argc, char** argv) {
  if (argc != 4) {
    std::fputs("expected tmux, socket and config paths\n", stderr);
    return 1;
  }
  const auto server = libtmux::Server::at_socket_path(
      argv[2], {}, {.tmux_binary = argv[1]});
  if (!server) {
    std::fprintf(stderr, "%s\n", server.error().diagnostic.c_str());
    return 1;
  }
  const auto sessions = server->sessions();
  if (!sessions) {
    std::fprintf(stderr, "%s\n", sessions.error().diagnostic.c_str());
    return 1;
  }
  if (sessions->empty()) {
    std::fputs("expected the owned demo session\n", stderr);
    return 1;
  }
  const auto editor = sessions->front().new_window({.name = "editor"});
  if (!editor) {
    std::fprintf(stderr, "%s\n", editor.error().diagnostic.c_str());
    return 1;
  }
  const auto logs = editor->split({
      .horizontal = true, .shell_command = "/bin/sh", .percentage = 30,
  });
  if (!logs) {
    std::fprintf(stderr, "%s\n", logs.error().diagnostic.c_str());
    return 1;
  }
  const auto sent = logs->send_text("printf 'hello from %s\\n' libtmux");
  if (!sent) {
    std::fprintf(stderr, "%s\n", sent.error().diagnostic.c_str());
    return 1;
  }
  const auto entered = logs->send_key("Enter");
  if (!entered) {
    std::fprintf(stderr, "%s\n", entered.error().diagnostic.c_str());
    return 1;
  }
  const auto ready = logs->wait_for_text(
      "hello from libtmux", {.timeout = std::chrono::seconds{5}});
  if (!ready || !ready->matched) {
    std::fputs("output did not arrive\n", stderr);
    return 1;
  }
  const auto visible = logs->capture();
  if (!visible) {
    std::fprintf(stderr, "%s\n", visible.error().diagnostic.c_str());
    return 1;
  }
  for (const auto line : libtmux::capture_lines(*visible)) {
    if (line == "hello from libtmux") {
      std::puts("hello from libtmux");
      return 0;
    }
  }
  std::fputs("capture is missing the complete output line\n", stderr);
  return 1;
}

