import Foundation
import LibTmux

@main
struct Quickstart {
    static func main() async throws {
        guard CommandLine.arguments.count == 4 else {
            throw QuickstartError.argumentsMissing
        }
        let server = try Server(
            socketPath: CommandLine.arguments[2],
            tmuxExecutable: CommandLine.arguments[1])
        let session = try await server.newSession(
            named: "work", windowName: "editor")
        let logs = try await server.newWindow(
            in: session, named: "logs").window
        let pane = try await server.splitWindow(logs, direction: .right)
        try await server.run("printf 'hello from %s\\n' libtmux", in: pane)

        let clock = ContinuousClock()
        let deadline = clock.now.advanced(by: .seconds(5))
        while clock.now < deadline {
            let lines = try await server.capture(pane)
            if lines.contains("hello from libtmux") {
                print("hello from libtmux")
                return
            }
            try await Task.sleep(for: .milliseconds(25))
        }
        throw QuickstartError.outputTimedOut
    }

    enum QuickstartError: Error {
        case argumentsMissing
        case outputTimedOut
    }
}
